  "html": "<div style=\"position:relative;min-height:300px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:18px;padding:24px;overflow:hidden;border-radius:14px;font-family:var(--sans)\"><div class=\"fp-row\" style=\"flex-wrap:wrap;align-items:stretch;justify-content:center;gap:14px;width:100%\"><div class=\"fp-col\" style=\"flex:1 1 150px;min-width:140px;gap:8px;align-items:center\"><span class=\"fp-tag\" style=\"color:var(--mut)\">потоки</span><div class=\"fp-box fp-col\" style=\"gap:8px;padding:12px;width:100%;box-sizing:border-box\"><div class=\"fp-row\" style=\"gap:10px;align-items:center;justify-content:space-between;width:100%\"><span class=\"fp-node good fp-pulse-g\" style=\"width:36px;height:36px;display:flex;align-items:center;justify-content:center;font:11px var(--mono)\">T1</span><span class=\"pr-blink\" style=\"font:10px var(--mono);color:var(--good)\">&#128273; захватил</span></div><div class=\"fp-row\" style=\"gap:10px;align-items:center;justify-content:space-between;width:100%\"><span class=\"fp-node mut pr-blink\" style=\"width:36px;height:36px;display:flex;align-items:center;justify-content:center;font:11px var(--mono);animation-delay:.5s\">T2</span><span style=\"font:10px var(--mono);color:var(--warn)\">&#9203; ждёт</span></div><div class=\"fp-row\" style=\"gap:10px;align-items:center;justify-content:space-between;width:100%\"><span class=\"fp-node mut pr-blink\" style=\"width:36px;height:36px;display:flex;align-items:center;justify-content:center;font:11px var(--mono);animation-delay:1s\">T3</span><span style=\"font:10px var(--mono);color:var(--warn)\">&#9203; ждёт</span></div></div><span class=\"fp-tag\" style=\"color:var(--mut)\">очередь ожидания</span></div><div class=\"fp-col\" style=\"flex:1 1 90px;min-width:80px;justify-content:center;align-items:center;gap:8px\"><span class=\"fp-tag pr-blink\" style=\"color:var(--acc)\">lock()</span><div style=\"position:relative;width:100%;height:24px;display:flex;align-items:center\"><div class=\"fp-conn\" style=\"width:100%\"></div><span class=\"fp-token fp-travel\" style=\"position:absolute\">&#128273;</span></div><span class=\"pr-blink\" style=\"font:10px var(--mono);color:var(--bad);animation-delay:.7s\">T2 T3 &rarr; &times;</span></div><div class=\"fp-col\" style=\"flex:1 1 110px;min-width:100px;gap:8px;align-items:center;justify-content:center\"><span class=\"fp-tag\" style=\"color:var(--warn)\">mutex</span><div class=\"fp-node fp-pulse-a\" style=\"width:64px;height:64px;display:flex;align-items:center;justify-content:center;font-size:26px\"><span class=\"pr-scale\">&#128274;</span></div><span class=\"fp-tag\" style=\"color:var(--mut)\">владелец: <span style=\"color:var(--good)\">T1</span></span></div><div class=\"fp-col\" style=\"flex:0 0 auto;justify-content:center;color:var(--good)\"><span class=\"fp-arrow pr-flow\" style=\"animation-delay:.4s\">&rarr;</span></div><div class=\"fp-col\" style=\"flex:1 1 150px;min-width:140px;gap:8px;align-items:center\"><span class=\"fp-tag\" style=\"color:var(--good)\">критическая секция</span><div class=\"fp-box pr-glow fp-col\" style=\"gap:8px;padding:12px;width:100%;box-sizing:border-box;align-items:center;border-color:var(--good);animation-delay:.6s\"><span class=\"fp-node good pr-bob\" style=\"width:36px;height:36px;display:flex;align-items:center;justify-content:center;font:11px var(--mono)\">T1</span><span style=\"font:10px var(--mono);color:var(--txt)\">balance = balance + 1</span><div class=\"fp-bar\" style=\"width:100%\"><span class=\"pr-flow\" style=\"display:block;height:100%;width:100%;background:var(--good);border-radius:inherit\"></span></div></div><span class=\"fp-tag\" style=\"color:var(--good)\">внутри &mdash; ровно один</span></div></div><div class=\"fp-row\" style=\"gap:8px;align-items:center;justify-content:center;flex-wrap:wrap\"><span class=\"fp-tag pr-fade\" style=\"color:var(--acc2)\">unlock()</span><span class=\"fp-arrow pr-flow\" style=\"color:var(--acc2);animation-delay:.8s\">&rarr;</span><span class=\"fp-token pr-bob\">&#128273;</span><span class=\"fp-arrow pr-flow\" style=\"color:var(--acc2);animation-delay:1.2s\">&rarr;</span><span class=\"fp-tag pr-blink\" style=\"color:var(--warn);animation-delay:1.4s\">следующий: T2</span></div><div class=\"fp-ver\" style=\"font:11px var(--mono);color:var(--mut);text-align:center;max-width:500px\">mutex пускает в критическую секцию <span style=\"color:var(--good)\">ровно один поток</span>; остальные <span style=\"color:var(--warn)\">блокируются в очереди</span> и получают &#128273; только после <span style=\"color:var(--acc2)\">unlock()</span></div></div>"
